<script setup lang="ts">
import { onMounted, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage } from 'element-plus'
import PageHeader from '@/components/PageHeader.vue'
import DatePicker from '@/components/DatePicker.vue'
import MemberSelect from '@/components/MemberSelect.vue'
import { accessApi, adminApi, featureApi } from '@/api'
import { useAppStore } from '@/stores/app'
import { requireTreeId } from '@/utils/backend'
const props=defineProps<{resource:string;title:string}>(),route=useRoute(),app=useAppStore(),items=ref<Record<string,any>[]>([]),dialog=ref(false),form=reactive({title:'',content:'',memberId:'' as number|'',eventType:'',eventDate:'',place:'',description:'',username:'',password:'',role:'MEMBER'})
async function load(){if(props.resource==='stories')items.value=await featureApi.stories(requireTreeId(app.activeTreeId));else if(props.resource==='events')items.value=await featureApi.events(requireTreeId(app.activeTreeId));else if(props.resource==='users')items.value=await adminApi.users();else items.value=[]}
async function save(){const tree=props.resource!=='users'?requireTreeId(app.activeTreeId):0;if(props.resource==='stories')await featureApi.createStory(tree,{title:form.title,content:form.content,memberId:Number(form.memberId)||undefined});else if(props.resource==='events')await featureApi.createEvent(tree,{title:form.title,eventType:form.eventType,eventDate:form.eventDate,datePrecision:'DAY',place:form.place,description:form.description,memberId:Number(form.memberId)||undefined});else if(props.resource==='users')await adminApi.createUser({username:form.username,password:form.password,role:form.role as 'ADMIN'|'MEMBER'});ElMessage.success('已保存');dialog.value=false;load()}
function setEnabled(id: number, value: unknown) { return adminApi.setEnabled(id,Boolean(value)) }
watch(()=>route.path,load);onMounted(load)
</script>
<template><PageHeader :title="title" :description="resource==='media'?'后端媒体仅提供上传与按 ID 下载，上传入口位于成员详情':resource==='stories'?'家族故事和回忆录':resource==='events'?'家族事件与提醒日期':'系统用户管理（仅 ADMIN）'"><el-button v-if="resource!=='media'" v-permission="'data:manage'" type="primary" @click="dialog=true">新增</el-button></PageHeader><section class="panel"><el-table :data="items" stripe><el-table-column :prop="resource==='users'?'username':'title'" :label="resource==='users'?'用户名':'标题'"/><el-table-column v-if="resource==='stories'" prop="content" label="内容" show-overflow-tooltip/><el-table-column v-if="resource==='events'" prop="eventDate" label="事件日期"/><el-table-column v-if="resource==='events'" prop="eventType" label="类型"/><el-table-column v-if="resource==='users'" prop="role" label="系统角色"/><el-table-column v-if="resource==='users'" prop="enabled" label="启用"><template #default="{row}"><el-switch v-model="row.enabled" @change="setEnabled(row.id,$event)"/></template></el-table-column><el-table-column prop="createdAt" label="创建时间"/></el-table><el-result v-if="resource==='media'" icon="info" title="媒体资料通过成员详情上传" sub-title="后端未提供媒体列表或删除接口；已避免调用不存在的 API"><template #extra><el-button type="primary" @click="$router.push('/members')">前往成员管理</el-button></template></el-result><el-empty v-else-if="!items.length" description="暂无记录"/></section><el-dialog v-model="dialog" :title="`新增${title}`" width="min(560px,94vw)"><el-form label-position="top"><template v-if="resource==='users'"><el-form-item label="用户名"><el-input v-model="form.username"/></el-form-item><el-form-item label="初始密码（至少 10 位）"><el-input v-model="form.password" type="password"/></el-form-item><el-form-item label="角色"><el-radio-group v-model="form.role"><el-radio value="MEMBER">成员</el-radio><el-radio value="ADMIN">管理员</el-radio></el-radio-group></el-form-item></template><template v-else><el-form-item label="标题"><el-input v-model="form.title"/></el-form-item><el-form-item label="关联成员（可选）"><MemberSelect v-model="form.memberId" :tree-id="app.activeTreeId"/></el-form-item><template v-if="resource==='events'"><el-form-item label="事件类型"><el-input v-model="form.eventType"/></el-form-item><el-form-item label="事件日期"><DatePicker v-model="form.eventDate" placeholder="请选择事件日期"/></el-form-item><el-form-item label="地点"><el-input v-model="form.place"/></el-form-item><el-form-item label="说明"><el-input v-model="form.description" type="textarea"/></el-form-item></template><el-form-item v-else label="正文"><el-input v-model="form.content" type="textarea" :rows="8"/></el-form-item></template></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></template>
